def modinv(a, m):
    # returns inverse of a mod m if gcd(a,m)==1
    a = a % m
    if a == 0 or gcd(a,m) != 1:
        return None
    # extended Euclid
    t, newt = 0, 1
    r, newr = m, a
    while newr != 0:
        q = r // newr
        t, newt = newt, t - q*newt
        r, newr = newr, r - q*newr
    if r > 1:
        return None
    if t < 0:
        t += m
    return t

def count_class(N, m, r):
